INSERT INTO dimensions (id, referentiel_id, position, libelle, libelle_court) VALUES (1, 1, 0, 'La joie et les circonstances', 'Circonstances');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (1, 1, 0, 'Je garde une attitude positive même quand les choses vont mal.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (2, 1, 1, 'Ma joie ne dépend pas uniquement de ce qui m’arrive.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (3, 1, 2, 'Je reste stable émotionnellement dans les changements.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (4, 1, 3, 'Je trouve des raisons d’être reconnaissant même dans des situations difficiles.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (5, 1, 4, 'Je garde un état intérieur paisible malgré les imprévus.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (6, 1, 5, 'Je peux me réjouir même quand mes plans échouent.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (7, 1, 6, 'Je garde une attitude constructive dans les difficultés.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (8, 1, 7, 'Je suis capable de voir le positif dans des situations négatives.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (9, 1, 8, 'Je ne laisse pas mes émotions dépendre des circonstances.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (10, 1, 9, 'Je garde une joie intérieure même dans l’incertitude.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (11, 1, 10, 'Mon humeur dépend fortement de ce qui m’arrive.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (12, 1, 11, 'Je perds facilement ma joie quand les choses tournent mal.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (13, 1, 12, 'Je suis déstabilisé par les imprévus.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (14, 1, 13, 'Je me décourage rapidement.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (15, 1, 14, 'Les difficultés affectent fortement mon moral.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (16, 1, 15, 'Je suis joyeux seulement quand tout va bien.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (17, 1, 16, 'Je laisse les circonstances contrôler mon état intérieur.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (18, 1, 17, 'Je suis souvent négatif face aux difficultés.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (19, 1, 18, 'Je perds facilement mon enthousiasme.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (20, 1, 19, 'Mon état dépend des événements extérieurs.', 'DIRECTE');
INSERT INTO dimensions (id, referentiel_id, position, libelle, libelle_court) VALUES (2, 1, 1, 'La joie et les épreuves', 'Épreuves');
