INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (28, 2, 7, 'Je vois les épreuves comme des opportunités de croissance.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (29, 2, 8, 'Je reste debout intérieurement malgré les crises.', 'DIRECTE');
