INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (31, 2, 10, 'Les épreuves me font perdre toute joie.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (32, 2, 11, 'Je me sens écrasé par les difficultés.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (33, 2, 12, 'Je perds espoir dans les moments difficiles.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (34, 2, 13, 'Je vois les épreuves comme injustes uniquement.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (35, 2, 14, 'Je me décourage facilement.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (36, 2, 15, 'Je deviens amer face aux difficultés.', 'INVERSE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (37, 2, 16, 'Je perds confiance dans les épreuves.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (38, 2, 17, 'Je suis submergé émotionnellement.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (39, 2, 18, 'Je vois peu de sens dans les difficultés.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (40, 2, 19, 'Les épreuves me rendent négatif.', 'DIRECTE');
INSERT INTO dimensions (id, referentiel_id, position, libelle, libelle_court) VALUES (3, 1, 2, 'Joie et relations', 'Relations');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (41, 3, 0, 'Ma joie dépend beaucoup de la qualité de mes relations.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (42, 3, 1, 'Je me sens moins heureux lorsque je suis seul.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (43, 3, 2, 'Mon bonheur dépend du regard des autres sur moi.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (44, 3, 3, 'Je me sens plus joyeux lorsque je suis entouré.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (45, 3, 4, 'Mon état intérieur dépend de l’ambiance relationnelle autour de moi.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (46, 3, 5, 'Je ressens un manque de joie lorsque mes relations sont tendues.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (47, 3, 6, 'Le fait d’être en couple (ou non) influence fortement ma joie.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (48, 3, 7, 'Je me sens moins heureux si je ne suis pas compris par les autres.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (49, 3, 8, 'Mes relations influencent fortement mon moral.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (50, 3, 9, 'Je perds facilement ma joie lorsque je suis en conflit avec quelqu’un.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (51, 3, 10, 'Je suis capable de rester joyeux même lorsque je suis seul.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (52, 3, 11, 'Ma joie ne dépend pas du regard des autres.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (53, 3, 12, 'Je garde une stabilité intérieure même lorsque mes relations sont difficiles.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (54, 3, 13, 'Mon état intérieur ne dépend pas de mon statut (célibataire, marié, etc.).', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (55, 3, 14, 'Je peux être en paix même sans validation extérieure.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (56, 3, 15, 'Je reste stable même lorsque je ne me sens pas compris.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (57, 3, 16, 'Je garde de la joie même dans les conflits relationnels.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (58, 3, 17, 'Ma joie ne dépend pas de la présence ou de l’absence des autres.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (59, 3, 18, 'Je trouve ma joie indépendamment de ma situation familiale.', 'DIRECTE');
INSERT INTO questions (id, dimension_id, position, texte, polarite) VALUES (60, 3, 19, 'Je reste intérieurement stable même lorsque mes relations changent.', 'DIRECTE');
